type ConfigConfigStoryboardScenes struct {
	client           *Clientset
	StoryboardScenes []baseconfigsaurientiov1.Child
}

func (n *ConfigConfigStoryboardScenes) Next(ctx context.Context) (*ConfigStoryboardScene, error) {
	for index, child := range n.StoryboardScenes {
		logger.Debugf("[ConfigConfigStoryboardScenes Next] Get next StoryboardScenes with name %s", child.Name)
		obj, err := n.client.Config().GetStoryboardSceneByName(ctx, child.Name)
		if err == nil {
			if index == len(n.StoryboardScenes)-1 {
				n.StoryboardScenes = nil
			} else {
				n.StoryboardScenes = n.StoryboardScenes[index+1:]
			}
			return obj, nil
		} else if errors.IsNotFound(err) {
			continue
		} else {
			return nil, err
		}
	}
	return nil, nil
}

