// Delete removes obj and all it's children from the database.
func (obj *ConfigRulebook) Delete(ctx context.Context) error {
	err := obj.client.Config().DeleteRulebookByName(ctx, obj.GetName())
	if err != nil {
		return err
	}
	obj.Rulebook = nil
	return nil
}

// Update updates spec of object in database. Children and Link can not be updated using this function.
func (obj *ConfigRulebook) Update(ctx context.Context) error {
	result, err := obj.client.Config().UpdateRulebookByName(ctx, obj.Rulebook)
	if err != nil {
		return err
	}
	obj.Rulebook = result.Rulebook
	return nil
}

