// GetMeters calculates hashed name of the object based on displayName and it's parents and returns the object
func (c *facilityInventorySaurientV1Chainer) GetMeters(ctx context.Context, displayName string) (result *InventoryMeter, err error) {
	hashedName := helper.GetHashedName("meters.inventory.saurient.io", c.parentLabels, displayName)
	logger.Debugf("[GetMeters] using chainer for name %s, displayName %s, labels %#v", hashedName, displayName, c.parentLabels)
	return c.client.Inventory().GetMeterByName(ctx, hashedName)
}

// AddMeters calculates hashed name of the child to create based on objToCreate.Name
// and parents names and creates it. objToCreate.Name is changed to the hashed name. Original name is preserved in
// nexus/display_name label and can be obtained using DisplayName() method.
func (c *facilityInventorySaurientV1Chainer) AddMeters(ctx context.Context,
	objToCreate *baseinventorysaurientiov1.Meter) (result *InventoryMeter, err error) {
	if objToCreate.Labels == nil {
		objToCreate.Labels = map[string]string{}
	}
	for k, v := range c.parentLabels {
		objToCreate.Labels[k] = v
	}
	if objToCreate.Labels[common.IsNameHashedLabel] != "true" {
		objToCreate.Labels[common.DisplayNameLabel] = objToCreate.GetName()
		objToCreate.Labels[common.IsNameHashedLabel] = "true"
		hashedName := helper.GetHashedName("meters.inventory.saurient.io", c.parentLabels, objToCreate.GetName())
		objToCreate.Name = hashedName
	}
	return c.client.Inventory().CreateMeterByName(ctx, objToCreate)
}

// DeleteMeters calculates hashed name of the child to delete based on displayName
// and parents names and deletes it.
func (c *facilityInventorySaurientV1Chainer) DeleteMeters(ctx context.Context, name string) (err error) {
	if c.parentLabels == nil {
		c.parentLabels = map[string]string{}
	}
	c.parentLabels[common.IsNameHashedLabel] = "true"
	hashedName := helper.GetHashedName("meters.inventory.saurient.io", c.parentLabels, name)
	return c.client.Inventory().DeleteMeterByName(ctx, hashedName)
}

