// DeleteMeterByName deletes object stored in the database under the hashedName which is a hash of
// display name and parents names. Use it when you know hashed name of object.
func (group *InventorySaurientV1) DeleteMeterByName(ctx context.Context, hashedName string) (err error) {
	logger.Debugf("[DeleteMeterByName] Received objectToDelete: %s", hashedName)
	var (
		retryCount int
		result     *baseinventorysaurientiov1.Meter
	)

	retryCount = 0
	for {
		result, err = group.client.baseClient.
			InventorySaurientV1().
			Meters().Get(ctx, hashedName, metav1.GetOptions{})
		if err != nil {
			logger.Errorf("[DeleteMeterByName] Failed to get Meters: %+v", err)
			if errors.IsTimeout(err) || customerrors.Is(err, context.DeadlineExceeded) {
				logger.Debugf("[Retry count: (%d) obj: %s ] %+v", retryCount, hashedName, err)
				if retryCount == maxRetryCount {
					logger.Errorf("Max retry exceed on get Meters: %s", hashedName)
					return err
				}
				retryCount += 1
				time.Sleep(sleepTime * time.Second)
			} else if customerrors.Is(err, context.Canceled) {
				logger.Errorf("[DeleteMeterByName] context canceled: %s", hashedName)
				return context.Canceled
			} else if errors.IsNotFound(err) {
				logger.Errorf("[DeleteMeterByName] Object: %s not found", hashedName)
				break
			} else {
				logger.Errorf("[DeleteMeterByName] Object: %s unexpected error: %+v", hashedName, err)
				return err
			}
		} else {
			break
		}
	}

	if result == nil {
		return err
	}

	retryCount = 0
	for {
		err = group.client.baseClient.
			InventorySaurientV1().
			Meters().Delete(ctx, hashedName, metav1.DeleteOptions{})
		if err != nil {
			logger.Errorf("[DeleteMeterByName] failed to delete Meters: %+v", err)
			if errors.IsTimeout(err) || customerrors.Is(err, context.DeadlineExceeded) {
				logger.Debugf("[Retry count: (%d) obj: %s ] %+v", retryCount, hashedName, err)
				if retryCount == maxRetryCount {
					logger.Errorf("Max retry exceed on delete Meters: %s", hashedName)
					return err
				}
				retryCount += 1
				time.Sleep(sleepTime * time.Second)
			} else if customerrors.Is(err, context.Canceled) {
				logger.Errorf("[DeleteMeterByName]: context canceled: %s", hashedName)
				return context.Canceled
			} else if errors.IsNotFound(err) {
				logger.Errorf("[DeleteMeterByName] Object: %s not found", hashedName)
				break
			} else {
				logger.Errorf("[DeleteMeterByName] Object: %s unexpected error: %+v", hashedName, err)
				return err
			}
		} else {
			if s, ok := group.client.subscriptions.Load("meters.inventory.saurient.io"); ok {
				s.(*subscription).WriteCacheObjects.Delete(hashedName)
			}
			break
		}
	}
	// Get Parent Node and check if gvk present before patch

	logger.Debugf("[DeleteMeterByName] Get parent details for object: %s", hashedName)
	// var patch Patch
	parents := result.GetLabels()
	if parents == nil {
		parents = make(map[string]string)
	}
	parentName, ok := parents["facilities.inventory.saurient.io"]
	if !ok {
		parentName = helper.DefaultKey
	}
	if result.GetLabels() != nil {
		if parents[common.IsNameHashedLabel] == "true" {
			parentName = helper.GetHashedName("facilities.inventory.saurient.io", parents, parentName)
		}
	} else {
		parentName = helper.GetHashedName("facilities.inventory.saurient.io", parents, parentName)
	}
	group.client.children.RemoveChild("facilities.inventory.saurient.io", parentName, "meters.inventory.saurient.io", hashedName)

	return nil
}

