// DeleteProductByName deletes object stored in the database under the hashedName which is a hash of
// display name and parents names. Use it when you know hashed name of object.
func (group *InventorySaurientV1) DeleteProductByName(ctx context.Context, hashedName string) (err error) {
	logger.Debugf("[DeleteProductByName] Received objectToDelete: %s", hashedName)
	var (
		retryCount int
		result     *baseinventorysaurientiov1.Product
	)

	retryCount = 0
	for {
		result, err = group.client.baseClient.
			InventorySaurientV1().
			Products().Get(ctx, hashedName, metav1.GetOptions{})
		if err != nil {
			logger.Errorf("[DeleteProductByName] Failed to get Products: %+v", err)
			if errors.IsTimeout(err) || customerrors.Is(err, context.DeadlineExceeded) {
				logger.Debugf("[Retry count: (%d) obj: %s ] %+v", retryCount, hashedName, err)
				if retryCount == maxRetryCount {
					logger.Errorf("Max retry exceed on get Products: %s", hashedName)
					return err
				}
				retryCount += 1
				time.Sleep(sleepTime * time.Second)
			} else if customerrors.Is(err, context.Canceled) {
				logger.Errorf("[DeleteProductByName] context canceled: %s", hashedName)
				return context.Canceled
			} else if errors.IsNotFound(err) {
				logger.Errorf("[DeleteProductByName] Object: %s not found", hashedName)
				break
			} else {
				logger.Errorf("[DeleteProductByName] Object: %s unexpected error: %+v", hashedName, err)
				return err
			}
		} else {
			break
		}
	}

	if result == nil {
		return err
	}

	for _, child := range group.client.children.GetChildren("products.inventory.saurient.io", hashedName, "logisticslegs.inventory.saurient.io") {
		err := group.client.Inventory().DeleteLogisticsLegByName(ctx, child)
		if err != nil && errors.IsNotFound(err) == false {
			return err
		}
		group.client.children.RemoveChild("products.inventory.saurient.io", hashedName, "logisticslegs.inventory.saurient.io", child)
	}

	retryCount = 0
	for {
		err = group.client.baseClient.
			InventorySaurientV1().
			Products().Delete(ctx, hashedName, metav1.DeleteOptions{})
		if err != nil {
			logger.Errorf("[DeleteProductByName] failed to delete Products: %+v", err)
			if errors.IsTimeout(err) || customerrors.Is(err, context.DeadlineExceeded) {
				logger.Debugf("[Retry count: (%d) obj: %s ] %+v", retryCount, hashedName, err)
				if retryCount == maxRetryCount {
					logger.Errorf("Max retry exceed on delete Products: %s", hashedName)
					return err
				}
				retryCount += 1
				time.Sleep(sleepTime * time.Second)
			} else if customerrors.Is(err, context.Canceled) {
				logger.Errorf("[DeleteProductByName]: context canceled: %s", hashedName)
				return context.Canceled
			} else if errors.IsNotFound(err) {
				logger.Errorf("[DeleteProductByName] Object: %s not found", hashedName)
				break
			} else {
				logger.Errorf("[DeleteProductByName] Object: %s unexpected error: %+v", hashedName, err)
				return err
			}
		} else {
			if s, ok := group.client.subscriptions.Load("products.inventory.saurient.io"); ok {
				s.(*subscription).WriteCacheObjects.Delete(hashedName)
			}
			break
		}
	}
	// Get Parent Node and check if gvk present before patch

	logger.Debugf("[DeleteProductByName] Get parent details for object: %s", hashedName)
	// var patch Patch
	parents := result.GetLabels()
	if parents == nil {
		parents = make(map[string]string)
	}
	parentName, ok := parents["tenants.inventory.saurient.io"]
	if !ok {
		parentName = helper.DefaultKey
	}
	if result.GetLabels() != nil {
		if parents[common.IsNameHashedLabel] == "true" {
			parentName = helper.GetHashedName("tenants.inventory.saurient.io", parents, parentName)
		}
	} else {
		parentName = helper.GetHashedName("tenants.inventory.saurient.io", parents, parentName)
	}
	group.client.children.RemoveChild("tenants.inventory.saurient.io", parentName, "products.inventory.saurient.io", hashedName)

	return nil
}

// CreateProductByName creates object in the database without hashing the name.
// Use it directly ONLY when objToCreate.Name is hashed name of the object.
func (group *InventorySaurientV1) CreateProductByName(ctx context.Context,
	objToCreate *baseinventorysaurientiov1.Product) (*InventoryProduct, error) {
	logger.Debugf("[CreateProductByName] Received objToCreate: %s", objToCreate.GetName())
	if objToCreate.GetLabels() == nil {
		objToCreate.Labels = make(map[string]string)
	}
	if _, ok := objToCreate.Labels[common.DisplayNameLabel]; !ok {
		objToCreate.Labels[common.DisplayNameLabel] = objToCreate.GetName()
	}

	objToCreate.Spec.LogisticsLegsGvk = nil

	var (
		retryCount int
		result     *baseinventorysaurientiov1.Product
		err        error
	)
	retryCount = 0
	for {
		result, err = group.client.baseClient.
			InventorySaurientV1().
			Products().Create(ctx, objToCreate, metav1.CreateOptions{})
		if err != nil {
			logger.Errorf("[CreateProductByName] Failed to create Product: %s, error: %+v", objToCreate.GetName(), err)
			if errors.IsTimeout(err) || customerrors.Is(err, context.DeadlineExceeded) {
				logger.Debugf("[Retry count: (%d) obj: %s ] %+v", retryCount, objToCreate.GetName(), err)
				if retryCount == maxRetryCount {
					logger.Errorf("Max retry exceed on create Product: %s", objToCreate.GetName())
					return nil, err
				}
				retryCount += 1
				time.Sleep(sleepTime * time.Second)
			} else if customerrors.Is(err, context.Canceled) {
				logger.Errorf("[CreateProductByName] context canceled while creating Product: %s", objToCreate.GetName())
				return nil, context.Canceled
			} else if errors.IsAlreadyExists(err) {
				logger.Debugf("[CreateProductByName] Product: %s already exists, error: %+v", objToCreate.GetName(), err)
				result, err = group.client.baseClient.InventorySaurientV1().Products().Get(ctx, objToCreate.GetName(), metav1.GetOptions{})
				if err != nil {
					logger.Fatalf("[CreateProductByName] Unable to Get Product %s after it was flagged as already exists, error: %+v", objToCreate.GetName(), err)
				}
				break
			} else {
				logger.Errorf("[CreateProductByName] found unexpected error while creating Product: %s, error: %+v", objToCreate.GetName(), err)
				return nil, err
			}
		} else {
			logger.Debugf("[CreateProductByName] Product: %s created successfully", objToCreate.GetName())
			if s, ok := group.client.subscriptions.Load("products.inventory.saurient.io"); ok {
				logger.Debugf("[CreateProductByName] Product: %s stored in wr-cache", objToCreate.GetName())
				s.(*subscription).WriteCacheObjects.Store(objToCreate.GetName(), result)
			}
			break
		}
	}

	parentName, ok := objToCreate.GetLabels()["tenants.inventory.saurient.io"]
	if !ok {
		parentName = helper.DefaultKey
	}
	parentHashedName := helper.GetHashedName("tenants.inventory.saurient.io", objToCreate.GetLabels(), parentName)

	group.client.children.AddChild("tenants.inventory.saurient.io", parentHashedName, "products.inventory.saurient.io", objToCreate.Name)

	logger.Debugf("[CreateProductByName] Executed Successfully: %s", objToCreate.GetName())
	return &InventoryProduct{
		client:  group.client,
		Product: result,
	}, nil
}

// UpdateProductByName updates object stored in the database under the hashedName which is a hash of
// display name and parents names.
