// GetLogisticsLegs returns child which has given displayName
func (obj *InventoryProduct) GetLogisticsLegs(ctx context.Context,
	displayName string) (result *InventoryLogisticsLeg, err error) {

	parentLabels := make(map[string]string)
	for k, v := range obj.Labels {
		parentLabels[k] = v
	}
	parentLabels["products.inventory.saurient.io"] = obj.DisplayName()
	childHashName := helper.GetHashedName("logisticslegs.inventory.saurient.io", parentLabels, displayName)
	logger.Debugf("[GetLogisticsLegs] in InventoryProduct with name %s, displayName %s, parentLabels %#v", childHashName, displayName, parentLabels)
	if obj.client.children.IsChildExists("products.inventory.saurient.io", obj.Name, "logisticslegs.inventory.saurient.io", childHashName) == false {
		logger.Debugf("[GetLogisticsLegs] ChildNotFound LogisticsLegs with name %s, displayName %s ", childHashName, displayName)
		return nil, NewChildNotFound(obj.DisplayName(), "Inventory.Product", "LogisticsLegs", displayName)
	}

	logger.Debugf("[GetLogisticsLegs] invoke GetLogisticsLegByName name %s, displayName %s", childHashName, displayName)
	result, err = obj.client.Inventory().GetLogisticsLegByName(ctx, childHashName)
	return
}

// AddLogisticsLegs calculates hashed name of the child to create based on objToCreate.Name
// and parents names and creates it. objToCreate.Name is changed to the hashed name. Original name is preserved in
// nexus/display_name label and can be obtained using DisplayName() method.
func (obj *InventoryProduct) AddLogisticsLegs(ctx context.Context,
	objToCreate *baseinventorysaurientiov1.LogisticsLeg) (result *InventoryLogisticsLeg, err error) {
	logger.Debugf("[AddLogisticsLegs] Received objToAdd: %s", objToCreate.GetName())
	if objToCreate.Labels == nil {
		objToCreate.Labels = map[string]string{}
	}
	for _, v := range helper.GetCRDParentsMap()["products.inventory.saurient.io"] {
		objToCreate.Labels[v] = obj.Labels[v]
	}
	objToCreate.Labels["products.inventory.saurient.io"] = obj.DisplayName()
	if objToCreate.Labels[common.IsNameHashedLabel] != "true" {
		objToCreate.Labels[common.DisplayNameLabel] = objToCreate.GetName()
		objToCreate.Labels[common.IsNameHashedLabel] = "true"
		hashedName := helper.GetHashedName(objToCreate.CRDName(), objToCreate.Labels, objToCreate.GetName())
		objToCreate.Name = hashedName
	}
	result, err = obj.client.Inventory().CreateLogisticsLegByName(ctx, objToCreate)
	logger.Debugf("[AddLogisticsLegs] LogisticsLeg created successfully: %s", objToCreate.GetName())
	updatedObj, getErr := obj.client.Inventory().GetProductByName(ctx, obj.GetName())
	if getErr == nil {
		obj.Product = updatedObj.Product
	}
	logger.Debugf("[AddLogisticsLegs] Executed Successfully: %s", objToCreate.GetName())
	return
}

// DeleteLogisticsLegs calculates hashed name of the child to delete based on displayName
// and parents names and deletes it.

func (obj *InventoryProduct) DeleteLogisticsLegs(ctx context.Context, displayName string) (err error) {
	logger.Debugf("[ DeleteLogisticsLegs] Received for LogisticsLeg object: %s to delete", displayName)

	parentLabels := make(map[string]string)
	for k, v := range obj.Labels {
		parentLabels[k] = v
	}
	parentLabels["products.inventory.saurient.io"] = obj.DisplayName()
	childHashName := helper.GetHashedName("logisticslegs.inventory.saurient.io", parentLabels, displayName)
	if obj.client.children.IsChildExists("products.inventory.saurient.io", obj.Name, "logisticslegs.inventory.saurient.io", childHashName) == false {
		return NewChildNotFound(obj.DisplayName(), "Inventory.Product", "LogisticsLegs", displayName)
	}

	err = obj.client.Inventory().DeleteLogisticsLegByName(ctx, childHashName)
	if err != nil {
		return err
	}
	logger.Debugf("[ DeleteLogisticsLegs] LogisticsLeg object: %s deleted successfully", displayName)
	updatedObj, err := obj.client.Inventory().GetProductByName(ctx, obj.GetName())
	if err == nil {
		obj.Product = updatedObj.Product
	}
	return
}

