// and parents names and deletes it.
func (c *productInventorySaurientV1Chainer) DeleteLogisticsLegs(ctx context.Context, name string) (err error) {
	if c.parentLabels == nil {
		c.parentLabels = map[string]string{}
	}
	c.parentLabels[common.IsNameHashedLabel] = "true"
	hashedName := helper.GetHashedName("logisticslegs.inventory.saurient.io", c.parentLabels, name)
	return c.client.Inventory().DeleteLogisticsLegByName(ctx, hashedName)
}

