func (group *InventorySaurientV1) CreateSupplierByName(ctx context.Context,
	objToCreate *baseinventorysaurientiov1.Supplier) (*InventorySupplier, error) {
	logger.Debugf("[CreateSupplierByName] Received objToCreate: %s", objToCreate.GetName())
	if objToCreate.GetLabels() == nil {
		objToCreate.Labels = make(map[string]string)
	}
	if _, ok := objToCreate.Labels[common.DisplayNameLabel]; !ok {
		objToCreate.Labels[common.DisplayNameLabel] = objToCreate.GetName()
	}

	objToCreate.Spec.DeclarationsGvk = nil

	var (
		retryCount int
		result     *baseinventorysaurientiov1.Supplier
		err        error
	)
	retryCount = 0
	for {
		result, err = group.client.baseClient.
			InventorySaurientV1().
			Suppliers().Create(ctx, objToCreate, metav1.CreateOptions{})
		if err != nil {
			logger.Errorf("[CreateSupplierByName] Failed to create Supplier: %s, error: %+v", objToCreate.GetName(), err)
			if errors.IsTimeout(err) || customerrors.Is(err, context.DeadlineExceeded) {
				logger.Debugf("[Retry count: (%d) obj: %s ] %+v", retryCount, objToCreate.GetName(), err)
				if retryCount == maxRetryCount {
					logger.Errorf("Max retry exceed on create Supplier: %s", objToCreate.GetName())
					return nil, err
				}
				retryCount += 1
				time.Sleep(sleepTime * time.Second)
			} else if customerrors.Is(err, context.Canceled) {
				logger.Errorf("[CreateSupplierByName] context canceled while creating Supplier: %s", objToCreate.GetName())
				return nil, context.Canceled
			} else if errors.IsAlreadyExists(err) {
				logger.Debugf("[CreateSupplierByName] Supplier: %s already exists, error: %+v", objToCreate.GetName(), err)
				result, err = group.client.baseClient.InventorySaurientV1().Suppliers().Get(ctx, objToCreate.GetName(), metav1.GetOptions{})
				if err != nil {
					logger.Fatalf("[CreateSupplierByName] Unable to Get Supplier %s after it was flagged as already exists, error: %+v", objToCreate.GetName(), err)
				}
				break
			} else {
				logger.Errorf("[CreateSupplierByName] found unexpected error while creating Supplier: %s, error: %+v", objToCreate.GetName(), err)
				return nil, err
			}
		} else {
			logger.Debugf("[CreateSupplierByName] Supplier: %s created successfully", objToCreate.GetName())
			if s, ok := group.client.subscriptions.Load("suppliers.inventory.saurient.io"); ok {
				logger.Debugf("[CreateSupplierByName] Supplier: %s stored in wr-cache", objToCreate.GetName())
				s.(*subscription).WriteCacheObjects.Store(objToCreate.GetName(), result)
			}
			break
		}
	}

	parentName, ok := objToCreate.GetLabels()["inventories.inventory.saurient.io"]
	if !ok {
		parentName = helper.DefaultKey
	}
	parentHashedName := helper.GetHashedName("inventories.inventory.saurient.io", objToCreate.GetLabels(), parentName)

	group.client.children.AddChild("inventories.inventory.saurient.io", parentHashedName, "suppliers.inventory.saurient.io", objToCreate.Name)

	logger.Debugf("[CreateSupplierByName] Executed Successfully: %s", objToCreate.GetName())
	return &InventorySupplier{
		client:   group.client,
		Supplier: result,
	}, nil
}

// UpdateSupplierByName updates object stored in the database under the hashedName which is a hash of
// display name and parents names.
func (group *InventorySaurientV1) UpdateSupplierByName(ctx context.Context,
	objToUpdate *baseinventorysaurientiov1.Supplier) (*InventorySupplier, error) {
	logger.Debugf("[UpdateSupplierByName] Received objToUpdate: %s", objToUpdate.GetName())

	var patch Patch

	if objToUpdate.Annotations != nil || objToUpdate.Labels != nil {
		current, err := group.client.Inventory().GetSupplierByName(ctx, objToUpdate.Name)
		if err != nil {
			return nil, err
		}

		if objToUpdate.Annotations != nil {
			if current.Annotations[ownershipAnnotation] != "" {
				objToUpdate.Annotations[ownershipAnnotation] = current.Annotations[ownershipAnnotation]
			}
			patch = append(patch, PatchOp{
				Op:    "replace",
				Path:  "/metadata/annotations",
				Value: objToUpdate.Annotations,
			})
		}

		if objToUpdate.Labels != nil {
			parentsList := helper.GetCRDParentsMap()["suppliers.inventory.saurient.io"]
			for _, k := range parentsList {
				objToUpdate.Labels[k] = current.Labels[k]
			}
			objToUpdate.Labels[common.IsNameHashedLabel] = current.Labels[common.IsNameHashedLabel]
			objToUpdate.Labels[common.DisplayNameLabel] = current.Labels[common.DisplayNameLabel]
			patch = append(patch, PatchOp{
				Op:    "replace",
				Path:  "/metadata/labels",
				Value: objToUpdate.Labels,
			})
		}
		patch = append(patch, PatchOp{
			Op:    "replace",
			Path:  "/metadata/finalizers",
			Value: objToUpdate.Finalizers,
		})
	}

	var rt reflect.Type

	rt = reflect.TypeOf(objToUpdate.Spec.SupplierID)
	if rt.Kind() == reflect.Slice || rt.Kind() == reflect.Array || rt.Kind() == reflect.Map {
		if !reflect.ValueOf(objToUpdate.Spec.SupplierID).IsNil() {
			patchValueSupplierID := objToUpdate.Spec.SupplierID
			patchOpSupplierID := PatchOp{
				Op:    "replace",
				Path:  "/spec/supplierID",
				Value: patchValueSupplierID,
			}
			patch = append(patch, patchOpSupplierID)
		}
	} else {
		patchValueSupplierID := objToUpdate.Spec.SupplierID
		patchOpSupplierID := PatchOp{
			Op:    "replace",
			Path:  "/spec/supplierID",
			Value: patchValueSupplierID,
		}
		patch = append(patch, patchOpSupplierID)
	}

	rt = reflect.TypeOf(objToUpdate.Spec.LegalName)
	if rt.Kind() == reflect.Slice || rt.Kind() == reflect.Array || rt.Kind() == reflect.Map {
		if !reflect.ValueOf(objToUpdate.Spec.LegalName).IsNil() {
			patchValueLegalName := objToUpdate.Spec.LegalName
			patchOpLegalName := PatchOp{
				Op:    "replace",
				Path:  "/spec/legalName",
				Value: patchValueLegalName,
			}
			patch = append(patch, patchOpLegalName)
		}
	} else {
		patchValueLegalName := objToUpdate.Spec.LegalName
		patchOpLegalName := PatchOp{
			Op:    "replace",
			Path:  "/spec/legalName",
			Value: patchValueLegalName,
		}
		patch = append(patch, patchOpLegalName)
	}

	rt = reflect.TypeOf(objToUpdate.Spec.Country)
	if rt.Kind() == reflect.Slice || rt.Kind() == reflect.Array || rt.Kind() == reflect.Map {
		if !reflect.ValueOf(objToUpdate.Spec.Country).IsNil() {
			patchValueCountry := objToUpdate.Spec.Country
			patchOpCountry := PatchOp{
				Op:    "replace",
				Path:  "/spec/country",
				Value: patchValueCountry,
			}
			patch = append(patch, patchOpCountry)
		}
	} else {
		patchValueCountry := objToUpdate.Spec.Country
		patchOpCountry := PatchOp{
			Op:    "replace",
			Path:  "/spec/country",
			Value: patchValueCountry,
		}
		patch = append(patch, patchOpCountry)
	}

	rt = reflect.TypeOf(objToUpdate.Spec.Tier)
	if rt.Kind() == reflect.Slice || rt.Kind() == reflect.Array || rt.Kind() == reflect.Map {
		if !reflect.ValueOf(objToUpdate.Spec.Tier).IsNil() {
			patchValueTier := objToUpdate.Spec.Tier
			patchOpTier := PatchOp{
				Op:    "replace",
				Path:  "/spec/tier",
				Value: patchValueTier,
			}
			patch = append(patch, patchOpTier)
		}
	} else {
		patchValueTier := objToUpdate.Spec.Tier
		patchOpTier := PatchOp{
			Op:    "replace",
			Path:  "/spec/tier",
			Value: patchValueTier,
		}
		patch = append(patch, patchOpTier)
	}

	marshaled, err := patch.Marshal()
	if err != nil {
		return nil, err
	}

	var (
		result *baseinventorysaurientiov1.Supplier
	)
	newCtx := context.TODO()
	retryCount := 0
	for {
		result, err = group.client.baseClient.
			InventorySaurientV1().
			Suppliers().Patch(newCtx, objToUpdate.GetName(), types.JSONPatchType, marshaled, metav1.PatchOptions{}, "")
		if err != nil {
			logger.Errorf("[UpdateSupplierByName] Failed to patch Supplier %s with error: %+v", objToUpdate.GetName(), err)
			if errors.IsTimeout(err) || customerrors.Is(err, context.DeadlineExceeded) {
				logger.Debugf("[Retry count: (%d) obj: %s ] %+v", retryCount, objToUpdate.GetName(), err)
				if retryCount == maxRetryCount {
					logger.Errorf("Max retry exceed on patching: %s", objToUpdate.GetName())
					logger.Debugf("Trigger Supplier Delete: %s", objToUpdate.GetName())
					delErr := group.DeleteSupplierByName(newCtx, objToUpdate.GetName())
					if delErr != nil {
						logger.Debugf("Error occur while deleting Supplier: %s", objToUpdate.GetName())
						return nil, delErr
					}
					logger.Debugf("Supplier deleted: %s", objToUpdate.GetName())
					return nil, err
				}
				retryCount += 1
				time.Sleep(sleepTime * time.Second)
			} else if customerrors.Is(err, context.Canceled) {
				logger.Errorf("[UpdateSupplierByName]: context canceled: %s", objToUpdate.GetName())
				return nil, context.Canceled
			} else {
				logger.Errorf("[UpdateSupplierByName] Object: %s unexpected error: %+v", objToUpdate.GetName(), err)
				logger.Debugf("Trigger Supplier Delete: %s", objToUpdate.GetName())
				delErr := group.DeleteSupplierByName(newCtx, objToUpdate.GetName())
				if delErr != nil {
					logger.Debugf("Error occur while deleting Supplier: %+v", objToUpdate.GetName())
					return nil, delErr
				}
				logger.Debugf("Supplier Deleted: %s", objToUpdate.GetName())
				return nil, err
			}
		} else {
			logger.Debugf("[UpdateSupplierByName] Patch Supplier Success :%s", objToUpdate.GetName())
			if s, ok := group.client.subscriptions.Load("suppliers.inventory.saurient.io"); ok {
				logger.Debugf("[UpdateSupplierByName] %s stored in wr-cache", objToUpdate.GetName())
				s.(*subscription).WriteCacheObjects.Store(objToUpdate.GetName(), result)
			}
			break
		}
	}
	logger.Debugf("[UpdateSupplierByName] Executed Successfully %s", objToUpdate.GetName())
	return &InventorySupplier{
		client:   group.client,
		Supplier: result,
	}, nil
}

// ListSuppliers returns slice of all existing objects of this type. Selectors can be provided in opts parameter.
func (group *InventorySaurientV1) ListSuppliers(ctx context.Context,
	opts metav1.ListOptions) (result []*InventorySupplier, err error) {
	key := "suppliers.inventory.saurient.io"
	if s, ok := group.client.subscriptions.Load(key); ok {
		items := s.(*subscription).informer.GetStore().List()
		result = make([]*InventorySupplier, len(items))
		for k, v := range items {
			item, _ := v.(*baseinventorysaurientiov1.Supplier)
			result[k] = &InventorySupplier{
				client:   group.client,
				Supplier: item.DeepCopy(),
			}
		}
	} else {
		list, err := group.client.baseClient.InventorySaurientV1().
			Suppliers().List(ctx, opts)
		if err != nil {
			return nil, err
		}
		result = make([]*InventorySupplier, len(list.Items))
		for k, v := range list.Items {
			item := v
			result[k] = &InventorySupplier{
				client:   group.client,
				Supplier: &item,
			}
		}
	}
	return
}

