type InventorySupplierDeclarations struct {
	client       *Clientset
	Declarations []baseinventorysaurientiov1.Child
}

func (n *InventorySupplierDeclarations) Next(ctx context.Context) (*InventoryDeclaration, error) {
	for index, child := range n.Declarations {
		logger.Debugf("[InventorySupplierDeclarations Next] Get next Declarations with name %s", child.Name)
		obj, err := n.client.Inventory().GetDeclarationByName(ctx, child.Name)
		if err == nil {
			if index == len(n.Declarations)-1 {
				n.Declarations = nil
			} else {
				n.Declarations = n.Declarations[index+1:]
			}
			return obj, nil
		} else if errors.IsNotFound(err) {
			continue
		} else {
			return nil, err
		}
	}
	return nil, nil
}

// GetAllDeclarationsIter returns an iterator for all children of given type
func (obj *InventorySupplier) GetAllDeclarationsIter(ctx context.Context) (
	result InventorySupplierDeclarations) {
	result.client = obj.client
	for _, v := range obj.client.children.GetChildren("suppliers.inventory.saurient.io", obj.Name, "declarations.inventory.saurient.io") {
		result.Declarations = append(result.Declarations, baseinventorysaurientiov1.Child{
			Group: "inventory.saurient.io",
			Kind:  "Declaration",
			Name:  v,
		})
	}
	return
}

