// GetDeclarationByName returns object stored in the database under the hashedName which is a hash of display
// name and parents names. Use it when you know hashed name of object.
func (group *InventorySaurientV1) GetDeclarationByName(ctx context.Context, hashedName string) (*InventoryDeclaration, error) {
	key := "declarations.inventory.saurient.io"
	if s, ok := group.client.subscriptions.Load(key); ok {
		// Check if the object is in write cache.
		resWrCache, inWrCache := s.(*subscription).WriteCacheObjects.Load(hashedName)
		item, exists, _ := s.(*subscription).informer.GetStore().GetByKey(hashedName)
		if exists {
			logger.Debugf("[GetDeclarationByName] Object: %s exists in cache", hashedName)
			resultCache, _ := item.(*baseinventorysaurientiov1.Declaration)
			subsCacheVersion, subsCacheVersionErr := strconv.Atoi(resultCache.ResourceVersion)
			if subsCacheVersionErr != nil {
				logger.Debugf("[GetDeclarationByName] Getting version of Object: %s failed with error %v", hashedName, subsCacheVersionErr)
			}

			writeCacheVersion := 0
			var writeCacheVersionErr error
			if inWrCache {
				writeCacheVersion, writeCacheVersionErr = strconv.Atoi(resWrCache.(*baseinventorysaurientiov1.Declaration).ResourceVersion)
				if writeCacheVersionErr != nil {
					logger.Debugf("[GetDeclarationByName] Getting version of Object: %s in write cache failed with error %v", hashedName, writeCacheVersionErr)
				}
			}

			if !inWrCache || subsCacheVersion >= writeCacheVersion {
				if inWrCache {
					s.(*subscription).WriteCacheObjects.Delete(hashedName)
				}
				return &InventoryDeclaration{
					client:      group.client,
					Declaration: resultCache.DeepCopy(),
				}, nil
			}
		}
		if inWrCache {
			return &InventoryDeclaration{
				client:      group.client,
				Declaration: resWrCache.(*baseinventorysaurientiov1.Declaration).DeepCopy(),
			}, nil
		}
	}

	retryCount := 0
	for {
		result, err := group.client.baseClient.
			InventorySaurientV1().
			Declarations().Get(ctx, hashedName, metav1.GetOptions{})
		if err == nil {
			return &InventoryDeclaration{
				client:      group.client,
				Declaration: result,
			}, nil
		} else if errors.IsNotFound(err) {
			logger.Debugf("[GetDeclarationByName]: object %v not found", hashedName)
			return nil, err
		} else {
			if errors.IsTimeout(err) || customerrors.Is(err, context.DeadlineExceeded) {
				logger.Debugf("[Retry count: (%d) obj: %s ] %+v", retryCount, hashedName, err)
				if retryCount == maxRetryCount {
					logger.Errorf("Max retry exceed on Get Declarations: %s", hashedName)
					return nil, err
				}
				retryCount += 1
				time.Sleep(sleepTime * time.Second)
			} else if customerrors.Is(err, context.Canceled) {
				logger.Errorf("[GetDeclarationByName]: %+v", err)
				return nil, context.Canceled
			} else {
				logger.Errorf("[GetDeclarationByName]: %+v", err)
				return nil, err
			}
		}
	}
}

// ForceReadDeclarationByName read object directly from the database under the hashedName which is a hash of display
// name and parents names. Use it when you know hashed name of object.
func (group *InventorySaurientV1) ForceReadDeclarationByName(ctx context.Context, hashedName string) (*InventoryDeclaration, error) {
	logger.Debugf("[ForceReadDeclarationByName] Received object :%s to read from DB", hashedName)
	retryCount := 0
	for {
		result, err := group.client.baseClient.
			InventorySaurientV1().
			Declarations().Get(ctx, hashedName, metav1.GetOptions{})
		if err != nil {
			logger.Errorf("[ForceReadDeclarationByName] Failed to Get Declarations: %+v", err)
			if errors.IsTimeout(err) || customerrors.Is(err, context.DeadlineExceeded) {
				logger.Errorf("[Retry Count: %d ] %+v", retryCount, err)
				if retryCount == maxRetryCount {
					logger.Errorf("Max Retry exceed on Get Declarations: %s", hashedName)
					return nil, err
				}
				retryCount += 1
				time.Sleep(sleepTime * time.Second)
			} else if customerrors.Is(err, context.Canceled) {
				logger.Errorf("[ForceReadDeclarationByName]: %+v", err)
				return nil, context.Canceled
			} else {
				logger.Errorf("[ForceReadDeclarationByName]: %+v", err)
				return nil, err
			}
		} else {
			logger.Debugf("[ForceReadDeclarationByName] Executed Successfully :%s", hashedName)
			return &InventoryDeclaration{
				client:      group.client,
				Declaration: result,
			}, nil
		}
	}
}

// DeleteDeclarationByName deletes object stored in the database under the hashedName which is a hash of
// display name and parents names. Use it when you know hashed name of object.
