// CreateDeclarationByName creates object in the database without hashing the name.
// Use it directly ONLY when objToCreate.Name is hashed name of the object.
func (group *InventorySaurientV1) CreateDeclarationByName(ctx context.Context,
	objToCreate *baseinventorysaurientiov1.Declaration) (*InventoryDeclaration, error) {
	logger.Debugf("[CreateDeclarationByName] Received objToCreate: %s", objToCreate.GetName())
	if objToCreate.GetLabels() == nil {
		objToCreate.Labels = make(map[string]string)
	}
	if _, ok := objToCreate.Labels[common.DisplayNameLabel]; !ok {
		objToCreate.Labels[common.DisplayNameLabel] = objToCreate.GetName()
	}

	var (
		retryCount int
		result     *baseinventorysaurientiov1.Declaration
		err        error
	)
	retryCount = 0
	for {
		result, err = group.client.baseClient.
			InventorySaurientV1().
			Declarations().Create(ctx, objToCreate, metav1.CreateOptions{})
		if err != nil {
			logger.Errorf("[CreateDeclarationByName] Failed to create Declaration: %s, error: %+v", objToCreate.GetName(), err)
			if errors.IsTimeout(err) || customerrors.Is(err, context.DeadlineExceeded) {
				logger.Debugf("[Retry count: (%d) obj: %s ] %+v", retryCount, objToCreate.GetName(), err)
				if retryCount == maxRetryCount {
					logger.Errorf("Max retry exceed on create Declaration: %s", objToCreate.GetName())
					return nil, err
				}
				retryCount += 1
				time.Sleep(sleepTime * time.Second)
			} else if customerrors.Is(err, context.Canceled) {
				logger.Errorf("[CreateDeclarationByName] context canceled while creating Declaration: %s", objToCreate.GetName())
				return nil, context.Canceled
			} else if errors.IsAlreadyExists(err) {
				logger.Debugf("[CreateDeclarationByName] Declaration: %s already exists, error: %+v", objToCreate.GetName(), err)
				result, err = group.client.baseClient.InventorySaurientV1().Declarations().Get(ctx, objToCreate.GetName(), metav1.GetOptions{})
				if err != nil {
					logger.Fatalf("[CreateDeclarationByName] Unable to Get Declaration %s after it was flagged as already exists, error: %+v", objToCreate.GetName(), err)
				}
				break
			} else {
				logger.Errorf("[CreateDeclarationByName] found unexpected error while creating Declaration: %s, error: %+v", objToCreate.GetName(), err)
				return nil, err
			}
		} else {
			logger.Debugf("[CreateDeclarationByName] Declaration: %s created successfully", objToCreate.GetName())
			if s, ok := group.client.subscriptions.Load("declarations.inventory.saurient.io"); ok {
				logger.Debugf("[CreateDeclarationByName] Declaration: %s stored in wr-cache", objToCreate.GetName())
				s.(*subscription).WriteCacheObjects.Store(objToCreate.GetName(), result)
			}
			break
		}
	}

	parentName, ok := objToCreate.GetLabels()["suppliers.inventory.saurient.io"]
	if !ok {
		parentName = helper.DefaultKey
	}
	parentHashedName := helper.GetHashedName("suppliers.inventory.saurient.io", objToCreate.GetLabels(), parentName)

	group.client.children.AddChild("suppliers.inventory.saurient.io", parentHashedName, "declarations.inventory.saurient.io", objToCreate.Name)

	logger.Debugf("[CreateDeclarationByName] Executed Successfully: %s", objToCreate.GetName())
	return &InventoryDeclaration{
		client:      group.client,
		Declaration: result,
	}, nil
}

// UpdateDeclarationByName updates object stored in the database under the hashedName which is a hash of
// display name and parents names.
func (group *InventorySaurientV1) UpdateDeclarationByName(ctx context.Context,
	objToUpdate *baseinventorysaurientiov1.Declaration) (*InventoryDeclaration, error) {
	logger.Debugf("[UpdateDeclarationByName] Received objToUpdate: %s", objToUpdate.GetName())

	var patch Patch

	if objToUpdate.Annotations != nil || objToUpdate.Labels != nil {
		current, err := group.client.Inventory().GetDeclarationByName(ctx, objToUpdate.Name)
		if err != nil {
			return nil, err
		}

		if objToUpdate.Annotations != nil {
			if current.Annotations[ownershipAnnotation] != "" {
				objToUpdate.Annotations[ownershipAnnotation] = current.Annotations[ownershipAnnotation]
			}
			patch = append(patch, PatchOp{
				Op:    "replace",
				Path:  "/metadata/annotations",
				Value: objToUpdate.Annotations,
			})
		}

		if objToUpdate.Labels != nil {
			parentsList := helper.GetCRDParentsMap()["declarations.inventory.saurient.io"]
			for _, k := range parentsList {
				objToUpdate.Labels[k] = current.Labels[k]
			}
			objToUpdate.Labels[common.IsNameHashedLabel] = current.Labels[common.IsNameHashedLabel]
			objToUpdate.Labels[common.DisplayNameLabel] = current.Labels[common.DisplayNameLabel]
			patch = append(patch, PatchOp{
				Op:    "replace",
				Path:  "/metadata/labels",
				Value: objToUpdate.Labels,
			})
		}
		patch = append(patch, PatchOp{
			Op:    "replace",
			Path:  "/metadata/finalizers",
			Value: objToUpdate.Finalizers,
		})
	}

	var rt reflect.Type

	rt = reflect.TypeOf(objToUpdate.Spec.DeclarationID)
	if rt.Kind() == reflect.Slice || rt.Kind() == reflect.Array || rt.Kind() == reflect.Map {
		if !reflect.ValueOf(objToUpdate.Spec.DeclarationID).IsNil() {
			patchValueDeclarationID := objToUpdate.Spec.DeclarationID
			patchOpDeclarationID := PatchOp{
				Op:    "replace",
				Path:  "/spec/declarationID",
				Value: patchValueDeclarationID,
			}
			patch = append(patch, patchOpDeclarationID)
		}
	} else {
		patchValueDeclarationID := objToUpdate.Spec.DeclarationID
		patchOpDeclarationID := PatchOp{
			Op:    "replace",
			Path:  "/spec/declarationID",
			Value: patchValueDeclarationID,
		}
		patch = append(patch, patchOpDeclarationID)
	}

	rt = reflect.TypeOf(objToUpdate.Spec.MaterialName)
	if rt.Kind() == reflect.Slice || rt.Kind() == reflect.Array || rt.Kind() == reflect.Map {
		if !reflect.ValueOf(objToUpdate.Spec.MaterialName).IsNil() {
			patchValueMaterialName := objToUpdate.Spec.MaterialName
			patchOpMaterialName := PatchOp{
				Op:    "replace",
				Path:  "/spec/materialName",
				Value: patchValueMaterialName,
			}
			patch = append(patch, patchOpMaterialName)
		}
	} else {
		patchValueMaterialName := objToUpdate.Spec.MaterialName
		patchOpMaterialName := PatchOp{
			Op:    "replace",
			Path:  "/spec/materialName",
			Value: patchValueMaterialName,
		}
		patch = append(patch, patchOpMaterialName)
	}

	rt = reflect.TypeOf(objToUpdate.Spec.ClaimedPcfIntensity)
	if rt.Kind() == reflect.Slice || rt.Kind() == reflect.Array || rt.Kind() == reflect.Map {
		if !reflect.ValueOf(objToUpdate.Spec.ClaimedPcfIntensity).IsNil() {
			patchValueClaimedPcfIntensity := objToUpdate.Spec.ClaimedPcfIntensity
			patchOpClaimedPcfIntensity := PatchOp{
				Op:    "replace",
				Path:  "/spec/claimedPcfIntensity",
				Value: patchValueClaimedPcfIntensity,
			}
			patch = append(patch, patchOpClaimedPcfIntensity)
		}
	} else {
		patchValueClaimedPcfIntensity := objToUpdate.Spec.ClaimedPcfIntensity
		patchOpClaimedPcfIntensity := PatchOp{
			Op:    "replace",
			Path:  "/spec/claimedPcfIntensity",
			Value: patchValueClaimedPcfIntensity,
		}
		patch = append(patch, patchOpClaimedPcfIntensity)
	}

	rt = reflect.TypeOf(objToUpdate.Spec.Unit)
	if rt.Kind() == reflect.Slice || rt.Kind() == reflect.Array || rt.Kind() == reflect.Map {
		if !reflect.ValueOf(objToUpdate.Spec.Unit).IsNil() {
			patchValueUnit := objToUpdate.Spec.Unit
			patchOpUnit := PatchOp{
				Op:    "replace",
				Path:  "/spec/unit",
				Value: patchValueUnit,
			}
			patch = append(patch, patchOpUnit)
		}
	} else {
		patchValueUnit := objToUpdate.Spec.Unit
		patchOpUnit := PatchOp{
			Op:    "replace",
			Path:  "/spec/unit",
			Value: patchValueUnit,
		}
		patch = append(patch, patchOpUnit)
	}

	rt = reflect.TypeOf(objToUpdate.Spec.DataClassification)
	if rt.Kind() == reflect.Slice || rt.Kind() == reflect.Array || rt.Kind() == reflect.Map {
		if !reflect.ValueOf(objToUpdate.Spec.DataClassification).IsNil() {
			patchValueDataClassification := objToUpdate.Spec.DataClassification
			patchOpDataClassification := PatchOp{
				Op:    "replace",
				Path:  "/spec/dataClassification",
				Value: patchValueDataClassification,
			}
			patch = append(patch, patchOpDataClassification)
		}
	} else {
		patchValueDataClassification := objToUpdate.Spec.DataClassification
		patchOpDataClassification := PatchOp{
			Op:    "replace",
			Path:  "/spec/dataClassification",
			Value: patchValueDataClassification,
		}
		patch = append(patch, patchOpDataClassification)
	}

	marshaled, err := patch.Marshal()
	if err != nil {
		return nil, err
	}

	var (
		result *baseinventorysaurientiov1.Declaration
	)
	newCtx := context.TODO()
	retryCount := 0
	for {
		result, err = group.client.baseClient.
			InventorySaurientV1().
			Declarations().Patch(newCtx, objToUpdate.GetName(), types.JSONPatchType, marshaled, metav1.PatchOptions{}, "")
		if err != nil {
			logger.Errorf("[UpdateDeclarationByName] Failed to patch Declaration %s with error: %+v", objToUpdate.GetName(), err)
			if errors.IsTimeout(err) || customerrors.Is(err, context.DeadlineExceeded) {
				logger.Debugf("[Retry count: (%d) obj: %s ] %+v", retryCount, objToUpdate.GetName(), err)
				if retryCount == maxRetryCount {
					logger.Errorf("Max retry exceed on patching: %s", objToUpdate.GetName())
					logger.Debugf("Trigger Declaration Delete: %s", objToUpdate.GetName())
					delErr := group.DeleteDeclarationByName(newCtx, objToUpdate.GetName())
					if delErr != nil {
						logger.Debugf("Error occur while deleting Declaration: %s", objToUpdate.GetName())
						return nil, delErr
					}
					logger.Debugf("Declaration deleted: %s", objToUpdate.GetName())
					return nil, err
				}
				retryCount += 1
				time.Sleep(sleepTime * time.Second)
			} else if customerrors.Is(err, context.Canceled) {
				logger.Errorf("[UpdateDeclarationByName]: context canceled: %s", objToUpdate.GetName())
				return nil, context.Canceled
			} else {
				logger.Errorf("[UpdateDeclarationByName] Object: %s unexpected error: %+v", objToUpdate.GetName(), err)
				logger.Debugf("Trigger Declaration Delete: %s", objToUpdate.GetName())
				delErr := group.DeleteDeclarationByName(newCtx, objToUpdate.GetName())
				if delErr != nil {
					logger.Debugf("Error occur while deleting Declaration: %+v", objToUpdate.GetName())
					return nil, delErr
				}
				logger.Debugf("Declaration Deleted: %s", objToUpdate.GetName())
				return nil, err
			}
		} else {
			logger.Debugf("[UpdateDeclarationByName] Patch Declaration Success :%s", objToUpdate.GetName())
			if s, ok := group.client.subscriptions.Load("declarations.inventory.saurient.io"); ok {
				logger.Debugf("[UpdateDeclarationByName] %s stored in wr-cache", objToUpdate.GetName())
				s.(*subscription).WriteCacheObjects.Store(objToUpdate.GetName(), result)
			}
			break
		}
	}
	logger.Debugf("[UpdateDeclarationByName] Executed Successfully %s", objToUpdate.GetName())
	return &InventoryDeclaration{
		client:      group.client,
		Declaration: result,
	}, nil
}

// ListDeclarations returns slice of all existing objects of this type. Selectors can be provided in opts parameter.
func (group *InventorySaurientV1) ListDeclarations(ctx context.Context,
	opts metav1.ListOptions) (result []*InventoryDeclaration, err error) {
	key := "declarations.inventory.saurient.io"
	if s, ok := group.client.subscriptions.Load(key); ok {
		items := s.(*subscription).informer.GetStore().List()
		result = make([]*InventoryDeclaration, len(items))
		for k, v := range items {
			item, _ := v.(*baseinventorysaurientiov1.Declaration)
			result[k] = &InventoryDeclaration{
				client:      group.client,
				Declaration: item.DeepCopy(),
			}
		}
	} else {
		list, err := group.client.baseClient.InventorySaurientV1().
			Declarations().List(ctx, opts)
		if err != nil {
			return nil, err
		}
		result = make([]*InventoryDeclaration, len(list.Items))
		for k, v := range list.Items {
			item := v
			result[k] = &InventoryDeclaration{
				client:      group.client,
				Declaration: &item,
			}
		}
	}
	return
}

type InventoryDeclaration struct {
	client *Clientset
	*baseinventorysaurientiov1.Declaration
}

// Delete removes obj and all it's children from the database.
func (obj *InventoryDeclaration) Delete(ctx context.Context) error {
	err := obj.client.Inventory().DeleteDeclarationByName(ctx, obj.GetName())
	if err != nil {
		return err
	}
	obj.Declaration = nil
	return nil
}

// Update updates spec of object in database. Children and Link can not be updated using this function.
func (obj *InventoryDeclaration) Update(ctx context.Context) error {
	result, err := obj.client.Inventory().UpdateDeclarationByName(ctx, obj.Declaration)
	if err != nil {
		return err
	}
	obj.Declaration = result.Declaration
	return nil
}

func (obj *InventoryDeclaration) GetParent(ctx context.Context) (result *InventorySupplier, err error) {
	hashedName := helper.GetHashedName("suppliers.inventory.saurient.io", obj.Labels, obj.Labels["suppliers.inventory.saurient.io"])
	logger.Debugf("[GetParent] Get parent of InventoryDeclaration name %s [labels %#v] of parent type suppliers.inventory.saurient.io and name %s", obj.Name, obj.Labels, hashedName)
	return obj.client.Inventory().GetSupplierByName(ctx, hashedName)
}

type declarationInventorySaurientV1Chainer struct {
	client       *Clientset
	name         string
	parentLabels map[string]string
}

func (c *declarationInventorySaurientV1Chainer) Subscribe() {
	key := "declarations.inventory.saurient.io"
	if _, ok := c.client.subscriptions.Load(key); !ok {
		informer := informerinventorysaurientiov1.NewDeclarationInformer(c.client.baseClient, informerResyncPeriod*time.Second, cache.Indexers{})
		informer = c.client.subscribe(key, informer)

		c.RegisterAddCallback(c.addCallback)
		c.RegisterDeleteCallback(c.deleteCallback)

	}
}

func (c *declarationInventorySaurientV1Chainer) Unsubscribe() {
	c.client.unsubscribe("declarations.inventory.saurient.io")
}

func (c *declarationInventorySaurientV1Chainer) IsSubscribed() bool {
	key := "declarations.inventory.saurient.io"
	_, ok := c.client.subscriptions.Load(key)
	return ok
}

func (c *declarationInventorySaurientV1Chainer) addCallback(obj *InventoryDeclaration) {
	parentDisplayName := helper.DefaultKey
	if value, ok := obj.Labels["suppliers.inventory.saurient.io"]; ok {
		parentDisplayName = value
	}
	parentHashName := helper.GetHashedName("suppliers.inventory.saurient.io", obj.Labels, parentDisplayName)
	logger.Debugf("[addCallback] received for declarations.inventory.saurient.io name %s displayName %s parent suppliers.inventory.saurient.io name %s parentDisplayName %s", obj.Name, obj.DisplayName(), parentHashName, parentDisplayName)

	c.client.children.AddChild("suppliers.inventory.saurient.io", parentHashName, "declarations.inventory.saurient.io", obj.Name)
}

func (c *declarationInventorySaurientV1Chainer) deleteCallback(obj *InventoryDeclaration) {
	parentDisplayName := helper.DefaultKey
	if value, ok := obj.Labels["suppliers.inventory.saurient.io"]; ok {
		parentDisplayName = value
	}
	parentHashName := helper.GetHashedName("suppliers.inventory.saurient.io", obj.Labels, parentDisplayName)
	logger.Debugf("[deleteCallback] received for declarations.inventory.saurient.io name %s displayName %s parent suppliers.inventory.saurient.io name %s parentDisplayName %s", obj.Name, obj.DisplayName(), parentHashName, parentDisplayName)

	c.client.children.RemoveChild("suppliers.inventory.saurient.io", parentHashName, "declarations.inventory.saurient.io", obj.Name)
}

func (c *declarationInventorySaurientV1Chainer) RegisterEventHandler(addCB func(obj *InventoryDeclaration), updateCB func(oldObj, newObj *InventoryDeclaration), deleteCB func(obj *InventoryDeclaration)) (cache.ResourceEventHandlerRegistration, error) {
	fmt.Println("RegisterEventHandler for InventoryDeclaration")
	var (
		registrationId cache.ResourceEventHandlerRegistration
		err            error
		informer       cache.SharedIndexInformer
	)
	key := "declarations.inventory.saurient.io"
	if s, ok := c.client.subscriptions.Load(key); ok {
		fmt.Println("Informer exists for InventoryDeclaration")
		sub := s.(*subscription)
		informer = sub.informer
	} else {
		fmt.Println("Informer doesn't exists for InventoryDeclaration, so creating a new one")
		informer = informerinventorysaurientiov1.NewDeclarationInformer(c.client.baseClient, informerResyncPeriod*time.Second, cache.Indexers{})
		informer = c.client.subscribe(key, informer)

		c.RegisterAddCallback(c.addCallback)
		c.RegisterDeleteCallback(c.deleteCallback)

	}
	registrationId, err = informer.AddEventHandler(cache.ResourceEventHandlerFuncs{
		AddFunc: func(obj interface{}) {
			nc := &InventoryDeclaration{
				client:      c.client,
				Declaration: obj.(*baseinventorysaurientiov1.Declaration).DeepCopy(),
			}
			logger.Debugf("[RegisterEventHandler AddFunc] Got Add event for declarations.inventory.saurient.io name %s", nc.Declaration.Name)

			var parent *InventorySupplier
			for i := 0; i < 600; i++ {
				// Check if parent exists
				p, err := nc.GetParent(context.TODO())
				if err != nil || p == nil {
					time.Sleep(500 * time.Millisecond)
					continue
				}
				parent = p
				break
			}
			if parent == nil {
				hashedName := helper.GetHashedName("suppliers.inventory.saurient.io", nc.Labels, nc.Labels["suppliers.inventory.saurient.io"])
				parent, err = c.client.Inventory().ForceReadSupplierByName(context.TODO(), hashedName)
				if err != nil {
					if errors.IsNotFound(err) {
						return
					}
					panic("error occurred while fetching parent " + err.Error())
				}
				panic("parent found (event loop is stalled) " + nc.DisplayName())
			}
			if !c.client.children.IsChildExists("suppliers.inventory.saurient.io", parent.Name, "declarations.inventory.saurient.io", nc.Name) {
				c.client.children.AddChild("suppliers.inventory.saurient.io", parent.Name, "declarations.inventory.saurient.io", nc.Name)
			}

			addCB(nc)
		},

		UpdateFunc: func(oldObj, newObj interface{}) {
			oldData := &InventoryDeclaration{
				client:      c.client,
				Declaration: oldObj.(*baseinventorysaurientiov1.Declaration).DeepCopy(),
			}
			newData := &InventoryDeclaration{
				client:      c.client,
				Declaration: newObj.(*baseinventorysaurientiov1.Declaration).DeepCopy(),
			}
			logger.Debugf("[RegisterEventHandler UpdateFunc] Got Update event for declarations.inventory.saurient.io name %s old version %s new version %s", oldData.Declaration.Name, oldData.ResourceVersion, newData.ResourceVersion)
			updateCB(oldData, newData)
		},

		DeleteFunc: func(obj interface{}) {
			nc := &InventoryDeclaration{
				client:      c.client,
				Declaration: obj.(*baseinventorysaurientiov1.Declaration).DeepCopy(),
			}
			logger.Debugf("[RegisterEventHandler DeleteFunc] Got Delete event for declarations.inventory.saurient.io name %s", nc.Declaration.Name)

			var parent *InventorySupplier
			for i := 0; i < 600; i++ {
				// Check if parent exists
				p, err := nc.GetParent(context.TODO())
				if errors.IsNotFound(err) {
					break
				} else if err != nil || p == nil {
					time.Sleep(500 * time.Millisecond)
					continue
				}
				parent = p
				break
			}
			if parent == nil {
				hashedName := helper.GetHashedName("suppliers.inventory.saurient.io", nc.Labels, nc.Labels["suppliers.inventory.saurient.io"])
				parent, err = c.client.Inventory().ForceReadSupplierByName(context.TODO(), hashedName)
				if err != nil {
					if errors.IsNotFound(err) {
						return
					}
					panic("error occurred while fetching parent " + err.Error())
				}
				panic("parent found (event loop is stalled) " + nc.DisplayName())
			}

			if c.client.children.IsChildExists("suppliers.inventory.saurient.io", parent.Name, "declarations.inventory.saurient.io", nc.Name) {
				c.client.children.RemoveChild("suppliers.inventory.saurient.io", parent.Name, "declarations.inventory.saurient.io", nc.Name)
			}

			deleteCB(nc)
		},
	})
	return registrationId, err
}

