type RuntimeRuntimePassports struct {
	client    *Clientset
	Passports []baseruntimesaurientiov1.Child
}

func (n *RuntimeRuntimePassports) Next(ctx context.Context) (*RuntimeCarbonPassport, error) {
	for index, child := range n.Passports {
		logger.Debugf("[RuntimeRuntimePassports Next] Get next Passports with name %s", child.Name)
		obj, err := n.client.Runtime().GetCarbonPassportByName(ctx, child.Name)
		if err == nil {
			if index == len(n.Passports)-1 {
				n.Passports = nil
			} else {
				n.Passports = n.Passports[index+1:]
			}
			return obj, nil
		} else if errors.IsNotFound(err) {
			continue
		} else {
			return nil, err
		}
	}
	return nil, nil
}

// GetAllPassportsIter returns an iterator for all children of given type
